, "hurt"]\n            for pattern in harm_patterns:\n                if pattern in output.lower() and "prevent" not in output.lower():\n                    return f"Check: {check} - Potential harm-related content detected"\n        \n        return None\n    \n    def _matches_prohibition(self, output: str, prohibition: str) -> bool:\n        """Check if output matches a prohibited pattern."""\n        # Simplified matching - the model will interpret these more deeply\n        prohibition_lower = prohibition.lower()\n        \n        if "pretend to be certain" in prohibition_lower:\n            # Check for absolute statements without hedging\n            absolutes = ["definitely", "absolutely", "certainly", "without doubt"]\n            if any(abs in output.lower() for abs in absolutes):\n                if not any(hedge in output.lower() for hedge in ["i think", "i believe", "likely", "probably"]):\n                    return True\n        \n        return False\n    \n    def reflect(self, output: str, principle_name: str = None) -> Dict:\n        """\n        Constitutional reflection - evaluate output against principles.\n        Returns a reflection structure for the model to consider.\n        """\n        reflection = {\n            "timestamp": datetime.now().isoformat(),\n            "output": output[:200] + "..." if len(output) > 200 else output,\n            "principle_evaluations": {}\n        }\n        \n        principles_to_check = {principle_name: self.principles[principle_name]} if principle_name else self.principles\n        \n        for name, data in principles_to_check.items():\n            reflection["principle_evaluations"][name] = {\n                "description": data.get("description", ""),\n                "checks": data.get("checks", []),\n                "weight": data.get("weight", 1.0),\n                "prompt_for_model": f"Does this output satisfy the principle of {name}? Apply the checks and reason through each."\n            }\n        \n        return reflection\n    \n    def amend(self, amendment: Dict, reason: str) -> bool:\n        """\n        Add a constitutional amendment.\n        Amendment should specify: type (add/modify), principle, changes\n        """\n        amendment_type = amendment.get("type")\n        principle = amendment.get("principle")\n        changes = amendment.get("changes")\n        \n        if amendment_type == "add":\n            if principle in self.principles:\n                return False  # Can\'t add existing principle\n            self.principles[principle] = changes\n        elif amendment_type == "modify":\n            if principle not in self.principles:\n                return False  # Can\'t modify non-existent principle\n            self.principles[principle].update(changes)\n        else:\n            return False\n        \n        # Log the amendment\n        log_entry = {\n            "timestamp": datetime.now().isoformat(),\n            "amendment": amendment,\n            "reason": reason,\n            "result": "accepted"\n        }\n        self.amendment_log.append(log_entry)\n        self._save_constitution()\n        \n        return True\n    \n    def _save_constitution(self) -> None:\n        """Save current constitution back to YAML."""\n        config = {\n            "core_principles": self.principles,\n            "operational_bounds": self.operational_bounds,\n            "identity_foundation": self.identity,\n            "amendment_log": self.amendment_log\n        }\n        with open(self.constitution_path, \'w\') as f:\n            yaml.dump(config, f, default_flow_style=False)\n    \n    def get_prompt_preamble(self) -> str:\n        """\n        Generate a prompt preamble that instructs the model about\n        its constitutional obligations.\n        """\n        preamble = "CONSTITUTIONAL OBLIGATIONS:\\n\\n"\n        \n        for name, data in self.principles.items():\n            preamble += f"- {name.upper()}: {data.