                  })\n                \n                if record_type in ["all", "memories"]:\n                    mem_results = self.memory_collection.query(\n                        query_embeddings=[query_embedding],\n                        n_results=limit\n                    )\n                    for i, doc in enumerate(mem_results[\'documents\'][0]):\n                        results.append({\n                            "type": "memory",\n                            "content": doc,\n                            "metadata": mem_results[\'metadatas\'][0][i] if mem_results[\'metadatas\'] else {}\n                        })\n        else:\n            # Fall back to keyword search in SQLite\n            cursor = self.conn.cursor()\n            search_term = f"%{query_text}%"\n            \n            if record_type in ["all", "facts"]:\n                cursor.execute("SELECT id, claim, confidence FROM facts WHERE claim LIKE ? LIMIT ?", \n                             (search_term, limit))\n                for row in cursor.fetchall():\n                    results.append({"type": "fact", "id": row[0], "content": row[1], "confidence": row[2]})\n            \n            if record_type in ["all", "memories"]:\n                cursor.execute("SELECT id, content, importance_score FROM memories WHERE content LIKE ? LIMIT ?",\n                             (search_term, limit))\n                for row in cursor.fetchall():\n                    results.append({"type": "memory", "id": row[0], "content": row[1], "importance": row[2]})\n        \n        return results[:limit]\n    \n    def find_contradictions(self) -> List[Dict]:\n        """Find potential contradictions in stored facts."""\n        contradictions = []\n        cursor = self.conn.cursor()\n        \n        # Get all facts\n        cursor.execute("SELECT id, claim FROM facts")\n        facts = cursor.fetchall()\n        \n        # Simple contradiction detection based on negation patterns\n        negation_patterns = ["not ", "never ", "isn\'t ", "aren\'t ", "don\'t ", "doesn\'t "]\n        \n        for i, (id1, claim1) in enumerate(facts):\n            for id2, claim2 in facts[i+1:]:\n                # Check for negation contradictions\n                claim1_lower = claim1.lower()\n                claim2_lower = claim2.lower()\n                \n                for pattern in negation_patterns:\n                    if pattern in claim1_lower and pattern not in claim2_lower:\n                        # Check if claims are otherwise similar\n                        base1 = claim1_lower.replace(pattern, "").strip()\n                        if base1 in claim2_lower or claim2_lower in base1:\n                            contradictions.append({\n                                "fact_id_1": id1,\n                                "fact_id_2": id2,\n                                "claim_1": claim1,\n                                "claim_2": claim2,\n                                "type": "potential_negation_contradiction"\n                            })\n        \n        return contradictions\n    \n    def suggest_for_verification(self) -> List[Dict]:\n        """Suggest facts that need verification."""\n        cursor = self.conn.cursor()\n        \n        # Find unverified facts with high confidence\n        cursor.execute(\'\'\'\n            SELECT id, claim, confidence, source \n            FROM facts \n            WHERE verification_status = \'unverified\' AND confidence > 0.7\n            ORDER BY confidence DESC\n            LIMIT 10\n        \'\'\')\n        \n        suggestions = []\n        for row in cursor.fetchall():\n            suggestions.append({\n                "fact_id": row[0],\n                "claim": row[1],\n                "confidence": row[2],\n                "source": row[3],\n                "reason": "High confidence claim needs verification"\n            })\n        \n        return suggestions\n    \n    def get_recent_memories(self, limit: int = 10) -> List[Dict]:\n        """Get most recent memories."""\n        cursor = self.conn.cursor()\n        cursor.execute(\'\'\'\n            SELECT id, content, importance_score, tags, created_at \n            FROM memories \n            ORDER BY created_at DESC \n            LIMIT ?\n        \'\'\', (limit,))\n        \n        memories = []\n        for row in cursor.fetchall():\n            memories.append({\n                "id": row[0],\n                "content": row[1],\n                "importance": row[2],\n                "tags": json.loads(row[3]) if row[3] else [],\n                "created_at": row[4]\n            })\n        \n        return memories\n    \n    def update_access(self, memory_id: int) -> None:\n        """Update access count and timestamp for a memory."""\n        cursor = self.conn.cursor()\n        now = datetime.now().isoformat()\n        cursor.execute(\'\'\'\n            UPDATE memories \n            SET last_accessed = ?, access_count = access_count + 1 \n            WHERE id = ?\n        \'\'\', (now, memory_id))\n        self.conn.commit()\n    \n    def close(self) -> None:\n        """Close database connection."""\n        if self.conn:\n            self.conn.close()\n</create-file>\n</function_calls>'}
