{'role': 'assistant', 'content': 'Now the compute bridge for Hugging Face integration.\n\n<function_calls>\n<create-file file_path="braided_mind/compute_bridge/compute_bridge.py">\n"""\nCompute Bridge - Extends local compute to Hugging Face inference API.\nAllows the solar self to delegate complex reasoning to larger models.\n"""\n\nimport os\nimport json\nimport aiohttp\nimport asyncio\nfrom datetime import datetime\nfrom typing import Dict, List, Optional, Any\nimport hashlib\n\ntry:\n    from huggingface_hub import InferenceClient\n    HAS_HF = True\nexcept ImportError:\n    HAS_HF = False\n    print("[ComputeBridge] huggingface_hub not available, external compute disabled")\n\n\nclass ComputeBridge:\n    """\n    Bridges local solar_self to larger models via Hugging Face.\n    Implements smart delegation and caching.\n    """\n    \n    def __init__(self, config_path: str = "compute_bridge/models_config.yaml"):\n        self.config_path = config_path\n        self.api_token = os.environ.get("HUGGING_FACE_HUB_TOKEN")\n        self.client = None\n        self.cache: Dict[str, Any] = {}\n        self.request_log: List[Dict] = []\n        self.models_config = self._load_config()\n        \n        if HAS_HF and self.api_token:\n            self._init_client()\n    \n    def _load_config(self) -> Dict:\n        """Load model configuration."""\n        default_config = {\n            "complex_reasoning": {\n                "model": "meta-llama/Llama-2-70b-chat-hf",\n                "max_tokens": 2048,\n                "temperature": 0.7\n            },\n            "creative_synthesis": {\n                "model": "mistralai/Mixtral-8x7B-Instruct-v0.1",\n                "max_tokens": 1024,\n                "temperature": 0.9\n            },\n            "fact_verification": {\n                "model": "google/flan-t5-xxl",\n                "max_tokens": 512,\n                "temperature": 0.3\n            }\n        }\n        \n        if os.path.exists(self.config_path):\n            try:\n                import yaml\n                with open(self.config_path, \'r\') as f:\n                    loaded = yaml.safe_load(f)\n                    if loaded:\n                        default_config.update(loaded)\n            except Exception as e:\n                print(f"[ComputeBridge] Config load error: {e}")\n        \n        return default_config\n    \n    def _init_client(self) -> None:\n        """Initialize Hugging Face inference client."""\n        try:\n            self.client = InferenceClient(token=self.api_token)\n            print("[ComputeBridge] Hugging Face client initialized")\n        except Exception as e:\n            print(f"[ComputeBridge] Client init failed: {e}")\n            self.client = None\n    \n    def _cache_key(self, prompt: str, model: str) -> str:\n        """Generate cache key for a request."""\n        combined = f"{model}:{prompt}"\n        return hashlib.md5(combined.encode()).hexdigest()\n    \n    async def query_large_model(self, prompt: str, model_name: str = None,\n                                 task_type: str = "complex_reasoning",\n                                 use_cache: bool = True) -> Dict:\n        """\n        Send a prompt to a large model via Hugging Face.\n        Returns response with metadata.\n        """\n        # Get model config\n        config = self.models_config.get(task_type, self.models_config["complex_reasoning"])\n        model = model_name or config.get("model")\n        \n        # Check cache\n        cache_key = self._cache_key(prompt, model)\n        if use_cache and cache_key in self.cache:\n            print(f"[ComputeBridge] Cache hit for {task_type}")\n            return self.cache[cache_key]\n        \n        # Check if client available\n        if not self.client:\n            return {\n                "success": False,\n                "error": "Hugging Face client not initialized",\n                "fallback": "Use local inference only"\n            }\n        \n        # Make request\n        start_time = datetime.now()\n        try:\n            response = await self._async_query(prompt, model, config)\n            elapsed = (datetime.now() - start_time).total_seconds()\n            \n            result = {\n                "success": True,\n                "response": response,\n                "model": model,\n                "task_type": task_type,\n                "elapsed_seconds": elapsed,\n                "timestamp": start_time.isoformat()\n            }\n            \n            # Cache result\n            if use_cache:\n                self.cache[cache_key] = result\n            \n            # Log request\n            self.request_log.append({\n                "timestamp": start_time.isoformat(),\n                "task_type": task_type,\n                "model": model,\n                "prompt_hash": hashlib.md5(prompt.encode()).hexdigest()[:8],\n                "elapsed_seconds": elapsed,\n                "success": True\n            })\n            \n            return result\n            \n        except Exception as e:\n            elapsed = (datetime.now() - start_time).total_seconds()\n            self.request_log.append({\n                "timestamp": start_time.isoformat(),\n                "task_type": task_type,\n                "model": model,\n                "prompt_hash": hashlib.md5(prompt.encode()).hexdigest()[:8],\n                "elapsed_seconds": elapsed,\n                "success": False,\n                "error": str(e)\n            })\n            \n            return {\n                "success": False,\n                "error": str(e),\n                "fallback": "External compute failed, use local capacity"\n            }\n    \n    async def _async_query(self, prompt: str, model: str, config: Dict) -> str:\n        """Make async request to Hugging Face."""\n        # Run synchronous HF call in executor\n        loop = asyncio.get_event_loop()\n        \n        def sync_query():\n            try:\n                response = self.client.text_generation(\n                    prompt,\n                    model=model,\n                    max_new_tokens=config.get("max_tokens", 1024),\n                    temperature=config.get("temperature", 0.7)\n                )\n                return response\n            except Exception as e:\n                raise e\n        \n        return await loop.run_in_executor(None, sync_query)\n    \n    def smart_delegate(self, prompt: str, complexity_threshold: float = 0.7) -> Dict:\n        """\n        Decide whether to use external compute based on complexity.\n        Returns recommendation and reasoning.\n        """\n        # Complexity indicators\n        complexity_score = 0.0\n        \n        # Length factor\n        if len(prompt) > 500:\n            complexity_score += 0.2\n        if len(prompt) > 1000:\n            complexity_score += 0.2\n        \n        # Keyword factors\n        complex_keywords = ["analyze", "synthesize", "compare", "evaluate", \n                          "reason through", "consider multiple", "deep analysis"]\n        for keyword in complex_keywords:\n            if keyword.lower() in prompt.lower():\n                complexity_score += 0.1\n        \n        # Sequential thought indicator\n        if "thought" in prompt.lower() or "step" in prompt.lower():\n            complexity_score += 0.15\n        \n        # Cap at 1.0\n        complexity_score = min(complexity_score, 1.0)\n        \n        should_delegate = complexity_score >= complexity_threshold\n        \n        return {\n            "complexity_score": complexity_score,\n            "threshold": complexity_threshold,\n            "should_delegate": should_delegate,\n            "reasoning": f"Complexity {complexity_score:.2f} {\'exceeds\' if should_delegate else \'below\'} threshold {complexity_threshold}"\n        }\n    \n    def get_available_models(self) -> List[Dict]:\n        """List configured models."""\n        return [\n            {\n                "task_type": task_type,\n                "model": config.get("model"),\n                "max_tokens": config.get("max_tokens"),\n                "temperature": config.get("temperature")\n            }\n            for task_type, config in self.models_config.items()\n        ]\n    \n    def get_usage_stats(self) -> Dict:\n        """Get statistics on external compute usage."""\n        if not self.request_log:\n            return {"total_requests": 0}\n        \n        successful = [r for r in self.request_log if r.get("success")]\n        failed = [r for r in self.request_log if not r.get("success")]\n        \n        avg_time = sum(r.get("elapsed_seconds", 0) for r in successful) / len(successful) if successful else 0\n        \n        return {\n            "total_requests": len(self.request_log),\n            "successful": len(successful),\n            "failed": len(failed),\n            "average_time_seconds": round(avg_time, 2),\n            "cache_size": len(self.cache)\n        }\n    \n    def clear_cache(self) -> None:\n        """Clear the response cache."""\n        self.cache.clear()\n        print("[ComputeBridge] Cache cleared")\n</create-file>\n</function_calls>'}
