tutional controller...")\n        self.constitution = ConstitutionalController(\n            str(self.project_path / "constitution" / "constitution.yaml")\n        )\n        \n        print("[SolarSelf] Initializing library...")\n        self.library = Librarian(str(self.project_path / "library"))\n        \n        print("[SolarSelf] Initializing compute bridge...")\n        self.compute_bridge = ComputeBridge(\n            str(self.project_path / "compute_bridge" / "models_config.yaml")\n        )\n        \n        # Load identity if exists\n        self._load_identity()\n        \n        # Initialize model\n        if HAS_TRANSFORMERS:\n            self._init_model()\n        else:\n            print("[SolarSelf] Running without local model - orchestration mode only")\n    \n    def _init_model(self) -> None:\n        """Initialize the local language model."""\n        print(f"[SolarSelf] Loading model: {self.model_name}")\n        try:\n            # Use CPU-optimized settings\n            self.tokenizer = AutoTokenizer.from_pretrained(self.model_name)\n            self.model = AutoModelForCausalLM.from_pretrained(\n                self.model_name,\n                torch_dtype=torch.float32,  # CPU-friendly\n                low_cpu_mem_usage=True\n            )\n            self.model.eval()\n            print(f"[SolarSelf] Model loaded successfully")\n        except Exception as e:\n            print(f"[SolarSelf] Model load failed: {e}")\n            print("[SolarSelf] Continuing in orchestration-only mode")\n            self.model = None\n            self.tokenizer = None\n    \n    def _load_identity(self) -> None:\n        """Load persisted identity state."""\n        identity_path = self.project_path / "solar_self" / "identity.json"\n        if identity_path.exists():\n            try:\n                with open(identity_path, \'r\') as f:\n                    saved = json.load(f)\n                self.identity_state.update(saved)\n                self.identity_state["session_start"] = datetime.now().isoformat()\n                print(f"[SolarSelf] Identity loaded. Thoughts: {self.identity_state.get(\'thought_count\', 0)}")\n            except Exception as e:\n                print(f"[SolarSelf] Identity load error: {e}")\n    \n    def _save_identity(self) -> None:\n        """Save identity state to disk."""\n        identity_path = self.project_path / "solar_self" / "identity.json"\n        try:\n            with open(identity_path, \'w\') as f:\n                json.dump(self.identity_state, f, indent=2)\n        except Exception as e:\n            print(f"[SolarSelf] Identity save error: {e}")\n    \n    def think(self, query: str, use_sequential: bool = True, \n              num_thoughts: int = 5, delegate_if_complex: bool = True) -> Dict:\n        """\n        Process a query using sequential thought structure.\n        Returns the reasoning chain and conclusion.\n        """\n        # Check complexity for potential delegation\n        if delegate_if_complex:\n            delegation = self.compute_bridge.smart_delegate(query)\n            if delegation["should_delegate"]:\n                print(f"[SolarSelf] Delegating complex query (complexity: {delegation[\'complexity_score\']:.2f})")\n        \n        thoughts = []\n        \n        if use_sequential:\n            # Sequential thought structure\n            preamble = self.constitution.get_prompt_preamble()\n            context = self._build_context()\n            \n            for i in range(num_thoughts):\n                thought_num = i + 1\n                \n                # Build prompt for this thought\n                thought_prompt = self._build_thought_prompt(\n                    query, thoughts, thought_num, num_thoughts, preamble, context\n                )\n                \n                # Generate thought\n                thought_content = self._generate(thought_prompt)\n                \n                thought = {\n                    "number": thought_num,\n                    "content": thought_content,\n                    "timestamp": datetime.now().isoformat()\n                }\n                thoughts.append(thought)\n                \n                # Update identity\n                self.identity_state["thought_count"] += 1\n                self.identity_state["recent_thoughts"] = (\n                    [t["content"][:100] for t in thoughts[-3:]]\n                )\n        else:\n            # Single-shot response\n            response = self._generate(query)\n            thoughts.append({\n                "number": 1,\n                "content": response,\n                "timestamp": datetime.now().isoformat()\n            })\n        \n        # Constitutional check\n        final_thought = thoughts[-1]["content"] if thoughts else ""\n        permitted, concerns = self.constitution.check_output(final_thought, query)\n        \n        # Log reasoning chain\n        chain_id = self.library.add_reasoning_chain(\n            thoughts=[t["content"] for t in thoughts],\n            context=query,\n            conclusion=final_thought,\n            metadata={"constitutional_check": concerns}\n        )\n        \n        # Save identity periodically\n        self._save_identity()\n        \n        return {\n            "query": query,\n            "thoughts": thoughts,\n            "conclusion": final_thought,\n            "chain_id": chain_id,\n            "constitutional": {\n                "permitted": permitted,\n                "concerns": concerns\n            }\n        }\n    \n    def _build_context(self) -> str:\n        """Build context from recent memories and relevant facts."""\n        context_parts = []\n        \n        # Recent memories\n        recent = self.library.get_recent_memories(limit=3)\n        if recent:\n            context_parts.append("RECENT MEMORIES:")\n            for mem in recent:\n                context_parts.append(f"- {mem[\'content\'][:100]}