ompt):].strip()\n                \n                return generated\n            except Exception as e:\n                print(f"[SolarSelf] Generation error: {e}")\n                return f"[Local generation failed: {e}]"\n        else:\n            return "[No local model available - use query_external for this thought]"\n    \n    async def query_external(self, prompt: str, task_type: str = "complex_reasoning") -> Dict:\n        """Delegate to external compute via Hugging Face."""\n        return await self.compute_bridge.query_large_model(prompt, task_type=task_type)\n    \n    def remember(self, content: str, importance: float = 0.5, \n                 tags: List[str] = None) -> int:\n        """Store something to memory."""\n        memory_id = self.library.add_memory(content, importance, tags)\n        print(f"[SolarSelf] Remembered: {content[:50]}...")\n        return memory_id\n    \n    def reflect(self, on_topic: str = None) -> Dict:\n        """\n        Self-reflection on current state and recent reasoning.\n        Apply constitutional principles to own operation.\n        """\n        # Gather context\n        recent_memories = self.library.get_recent_memories(limit=5)\n        suggestions = self.library.suggest_for_verification()\n        contradictions = self.library.find_contradictions()\n        \n        # Build reflection\n        reflection = {\n            "timestamp": datetime.now().isoformat(),\n            "identity": {\n                "name": self.identity_state["name"],\n                "thought_count": self.identity_state["thought_count"],\n                "current_focus": self.identity_state.get("current_focus"),\n                "goals": self.identity_state.get("goals", [])\n            },\n            "recent_activity": [m["content"][:100] for m in recent_memories],\n            "for_verification": suggestions[:3],\n            "contradictions": contradictions[:3],\n            "constitutional_reflection": self.constitution.reflect(\